/** @typedef {import("../types.mjs").Finding} Finding */
/** @typedef {import("../types.mjs").RuleContext} RuleContext */

export const id = "PC-02";
export const title = "Every config/routing.json tier's model names a provider present in config/models.json";
export const closes = ["REQ-PRV-07", "REQ-PRV-12a"];

/** @param {RuleContext} ctx @returns {Finding[]} */
export function run(ctx) {
  // config/routing.json and config/models.json are generated by the installer and git-ignored.
  // Before the first install only the tracked *.default.json templates are on disk, and the rule
  // has to check those instead — otherwise `pi-check` on a fresh clone reports the repo's own
  // shipped defaults as broken, which is exactly backwards.
  const ROUTING = ctx.exists("config/routing.json") ? "config/routing.json" : "config/routing.default.json";
  const MODELS = ctx.exists("config/models.json") ? "config/models.json" : "config/models.default.json";
  if (!ctx.exists(ROUTING)) return [];

  /** @type {Finding[]} */
  const findings = [];
  let routing, models;
  try {
    routing = ctx.readJSON(ROUTING);
  } catch (err) {
    return [{ rule: id, file: ROUTING, message: String(err.message ?? err) }];
  }
  if (!ctx.exists(MODELS)) {
    return [{ rule: id, file: MODELS, message: "config/models.json is missing — no tier can resolve a provider" }];
  }
  try {
    models = ctx.readJSON(MODELS);
  } catch (err) {
    return [{ rule: id, file: MODELS, message: String(err.message ?? err) }];
  }

  const providers = models && typeof models === "object" ? models.providers : undefined;
  const knownProviders = new Set(providers && typeof providers === "object" ? Object.keys(providers) : []);

  const tiers = routing && typeof routing === "object" ? routing.tiers : undefined;
  if (!tiers || typeof tiers !== "object" || Object.keys(tiers).length === 0) {
    findings.push({ rule: id, file: ROUTING, message: "routing.json has no tiers — nothing resolves" });
    return findings;
  }

  const fileLines = ctx.lines(ROUTING);
  for (const [tierName, tier] of Object.entries(tiers)) {
    const optional = tier && typeof tier === "object" && tier.optional === true;
    const model = tier && typeof tier === "object" ? tier.model : undefined;
    if (typeof model !== "string" || model.length === 0) {
      findings.push({ rule: id, file: ROUTING, message: `tier "${tierName}" has no "model" field` });
      continue;
    }
    const slash = model.indexOf("/");
    const provider = slash === -1 ? model : model.slice(0, slash);
    if (!knownProviders.has(provider)) {
      // `optional: true` tiers (e.g. a local lane that requires a not-always-running server)
      // may be legitimately unreachable at runtime, but the reference must still be
      // well-formed — a provider block with that name must still exist.
      const line = fileLines.find((l) => l.text.includes(`"${model}"`))?.line;
      findings.push({
        rule: id,
        file: ROUTING,
        line,
        message: `tier "${tierName}" model "${model}" names provider "${provider}", which has no block in config/models.json${optional ? " (optional: true does not exempt the reference itself)" : ""}`,
      });
    }
  }
  return findings;
}
